/// <summary>
/// PaffH 22.08.22
/// test NDXKeyVaultHelper::getKeyVaultSecretValue()
/// </summary>
public static void testKeyVault()
{
    try
    {
        const str keyVaultUri = 'https://azr-servicebus-vault.vault.azure.net/';
        const str keyVaultSecretName = 'NDX365FO01NS-ConnectionString';

        str connectionString = NDXKeyVaultHelper::getKeyVaultSecretValue(keyVaultUri, keyVaultSecretName);
        if (connectionString == '')
        {
            warning("@NDX:NDXKeyVaultValueCouldNotBeFound");
        }
        else
        {
            Info("@NDX:NDXKeyVaultValueFound");
        }

    }
    catch
    {
        error(strFmt("@NDXBase:NDXCallOfMethodWithError", 'NDXKeyVaultHelper::getKeyVaultSecretValue'));
    }
}

